package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A SNAPSHOT written for a person: the day the sheet's today was leaving, and their due-total then
 *  as the audit shows it ("n/a" when none). */
@Entity
@Table(name = "person_snapshot")
public class PersonSnapshot {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(name = "snapshot_day", nullable = false)
    private LocalDate day;

    @Column(name = "due_total", nullable = false)
    private String dueTotal;

    protected PersonSnapshot() {
    }

    public PersonSnapshot(String sheetId, Long personId, LocalDate day, String dueTotal) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.day = day;
        this.dueTotal = dueTotal;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public LocalDate getDay() {
        return day;
    }

    public String getDueTotal() {
        return dueTotal;
    }
}
EOF
cat > PersonSnapshotRepository.java <<'EOF'
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PersonSnapshotRepository extends JpaRepository<PersonSnapshot, Long> {

    /** The sheet's snapshots in the order they were written. */
    List<PersonSnapshot> findBySheetIdOrderByIdAsc(String sheetId);

    /** A person's snapshots in the order they were written. */
    List<PersonSnapshot> findByPersonIdOrderByIdAsc(Long personId);
}
